import { STORE_KEY, emptyState, cleanState, escapeHTML as h, makeReport, reportErrors } from './core.js';

const root = document.querySelector('#app');
let catalog, state = emptyState(), persist = false, storageAvailable = true;
const findJob = id => catalog.occupations.find(o => o.id === id);
const sourceFor = o => catalog.sources.find(s => s.id === o.source_id);
const selectedJobs = () => state.selected.map(findJob).filter(Boolean);
const button = (href, text, cls='') => `<a class="button ${cls}" href="${href}">${text}</a>`;
const status = '<span class="chip draft">현직자 검토 대기</span>';
const sourceNotice = '<div class="notice">업무 설명은 미국 O*NET의 관련 직업을 참고한 초안입니다. 국내 산업별 차이·업무환경·장단점은 아직 확인하지 않았습니다. 활동은 직접 만든 가상 사례이며 적성검사가 아닙니다.</div>';
function toast(message) {const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function save() {
  if (!persist) return;
  try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); }
  catch { persist=false;storageAvailable=false;toast('기기 저장에 실패했습니다. 현재 탭에서는 계속 작성할 수 있습니다.'); }
}
function download(name, value, type='application/json') {
  const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
function evidenceHTML(o) {
  return o.claim_ids.map(id=> {
    const c=catalog.claims.find(c=>c.id===id);
    return `<article class="evidence"><span class="chip">${h(c.category)}</span> ${status}<p>${h(c.statement)}</p><details><summary>출처와 근거 확인</summary><p>적용 범위: ${h(c.scope)}</p>${c.evidence_ids.map(eid=>{const e=catalog.evidence.find(e=>e.id===eid);const s=catalog.sources.find(s=>s.id===e.source_id);return `<blockquote lang="en">${h(e.excerpt)}</blockquote><a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗</a><p>${h(e.locator)} · 확인 ${h(s.retrieved_at)}</p>`;}).join('')}<p>${h(o.mapping_note)}</p></details></article>`;
  }).join('');
}
function renderExplore(query='') {
  const jobs=catalog.occupations.filter(o=>[o.name,o.subtitle,...o.tags].join(' ').includes(query));
  root.innerHTML=`<section class="hero"><div><span class="eyebrow">EXPLORE YOUR POSSIBILITIES</span><h1>직업 이름 너머,<br>내가 하게 될 일을 만나다.</h1><p>실제 업무의 근거를 살펴보고, 작은 활동으로 경험해 보세요.<br>서로 다른 직업을 비교하면 나의 선택 기준이 보이기 시작합니다.</p><div class="buttons">${button('#compare','선택한 직업 비교하기 ↗')}${button('#notebook','탐색 기록 이어쓰기','secondary')}</div></div><div class="hero-graphic" aria-label="탐색 과정: 업무 이해, 직업 비교, 선택 이유 기록"><span class="eyebrow" style="color:#dce7a6">FROM CURIOSITY TO CLARITY</span><div class="orbit" aria-hidden="true"></div><div class="orbit two" aria-hidden="true"></div><div class="route-line"><i>1</i> 어떤 일을 하는지 이해하기</div><div class="route-line"><i>2</i> 나에게 중요한 조건 비교하기</div><div class="route-line"><i>3</i> 선택의 이유와 다음 행동 기록하기</div><div class="graphic-note">정답을 정해 주기보다, 질문을 구체적으로.</div></div></section><div class="section-head"><div><h2>오늘 탐색할 직업</h2><p>관심 있는 직업을 두 개 이상 골라 같은 기준으로 비교해 보세요.</p></div><label><span class="small">직업 검색 </span><input class="search" id="search" type="search" placeholder="직업명 또는 업무 키워드" value="${h(query)}"></label></div><div class="grid">${jobs.map((o,i)=>`<article class="card"><div class="card-top"><span class="card-num">0${catalog.occupations.indexOf(o)+1} / EXPLORE</span>${status}</div><h3>${h(o.name)}</h3><p>${h(o.subtitle)}</p><div class="pill-row">${o.tags.map(t=>`<span class="chip">${h(t)}</span>`).join('')}<span class="chip">가상 활동 15분</span></div><div class="card-bottom"><label class="check-label"><input type="checkbox" data-select="${o.id}" ${state.selected.includes(o.id)?'checked':''}> 비교에 담기</label><a class="text-link" href="#job/${o.id}">업무 살펴보기 ↗</a></div></article>`).join('')}</div>${jobs.length?'':'<p class="empty">일치하는 직업이 없습니다. 현재는 세 직업을 제공하는 시제품입니다.</p>'}<div class="actionbar"><p id="selection-count">${state.selected.length}개 직업 선택 · 비교한 내용은 상담 보고서에 연결됩니다.</p>${button('#compare','나란히 비교하기 →','light')}</div><div class="trust-band"><div><strong>01 · 근거를 따라가는 정보</strong><p>설명마다 자료의 출처와 적용 범위를 확인합니다.</p></div><div><strong>02 · 나의 말로 남기는 기록</strong><p>정해진 결과 대신 직접 느낀 점과 질문을 적습니다.</p></div><div><strong>03 · 상담으로 이어지는 탐색</strong><p>선택 기준과 다음 행동을 보고서로 정리합니다.</p></div></div>`;
  document.querySelector('#search').addEventListener('input',e=>{const pos=e.target.selectionStart;renderExplore(e.target.value);const input=document.querySelector('#search');input.focus();if(input.type!=='search')input.setSelectionRange(pos,pos);});
}
function renderJob(id) {
  const o=findJob(id);if(!o){root.innerHTML='<p class="empty">직업을 찾을 수 없습니다. <a href="#explore">탐색으로 돌아가기</a></p>';return;}
  root.innerHTML=`<a class="back" href="#explore">← 직업 탐색으로</a><p class="eyebrow">UNDERSTAND THE WORK</p><h1 class="page-title">${h(o.name)}</h1><p class="lead">${h(o.subtitle)}</p>${sourceNotice}<div class="layout"><div><section class="panel"><h2>근거에서 확인한 업무</h2>${evidenceHTML(o)}</section><section class="panel"><div class="pill-row"><span class="chip">직접 만든 가상 사례</span><span class="chip">약 15분</span></div><h2>${h(o.scenario.title)}</h2><p>${h(o.scenario.context)}</p><ol class="step-list">${o.scenario.steps.map((s,i)=>`<li><b>0${i+1}</b>${h(s)}</li>`).join('')}</ol><p><strong>만들어 볼 결과물</strong><br>${h(o.scenario.deliverable)}</p><p class="small">실제 업무를 단순화한 탐색 활동입니다. 수행 결과로 적성이나 직무 능력을 판정하지 않습니다.</p>${button('#notebook/'+o.id,'이 활동 기록하기 →')}</section></div><aside><section class="panel"><h2>상담에서 더 확인할 것</h2><ul>${o.unknowns.map(s=>`<li>${h(s)}</li>`).join('')}</ul><p class="small">자료가 없는 조건을 점수로 채우지 않았습니다.</p></section><section class="panel"><h2>이 자료의 상태</h2><p>${status}</p><p class="small">미국 참고 자료 1건<br>국내 채용공고 연결 0건<br>현직자 검토 0건<br>버전 ${h(o.version)}</p><a href="${h(sourceFor(o).url)}" target="_blank" rel="noopener noreferrer">참고 자료 열기 ↗</a></section><div class="buttons">${button('#compare','다른 직업과 비교','secondary')}</div></aside></div>`;
}
function renderCompare() {
  const jobs=selectedJobs();
  root.innerHTML=`<span class="eyebrow">SIDE BY SIDE</span><h1 class="page-title">같은 질문으로, 다른 직업을 보다.</h1><p class="lead">업무 설명과 활동 예시를 구분해 비교하세요. 나에게 중요한 차이는 기록으로 남길 수 있습니다.</p><div class="pill-row">${catalog.occupations.map(o=>`<label class="check-label chip"><input type="checkbox" data-select="${o.id}" ${state.selected.includes(o.id)?'checked':''}>${h(o.name)}</label>`).join('')}</div>${jobs.length<2?'<div class="empty">비교할 직업을 두 개 이상 선택해 주세요.</div>':`<div class="table-wrap"><table class="comparison"><caption class="small">업무 설명은 미국 참고 자료 기반 초안 · 활동과 산출물은 가상 예시</caption><thead><tr><th scope="col">비교 기준</th>${jobs.map(o=>`<th scope="col"><a href="#job/${o.id}">${h(o.name)}</a><br>${status}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">참고 업무</th>${jobs.map(o=>`<td>${o.claim_ids.map(id=>`<p>${h(catalog.claims.find(c=>c.id===id).statement)}</p>`).join('')}<a href="#job/${o.id}">근거 확인 →</a></td>`).join('')}</tr><tr><th scope="row">활동에서<br>경험할 상황</th>${jobs.map(o=>`<td><span class="chip">가상 사례</span><p>${h(o.scenario.title)}</p></td>`).join('')}</tr><tr><th scope="row">활동 결과물</th>${jobs.map(o=>`<td>${h(o.scenario.deliverable)}</td>`).join('')}</tr><tr><th scope="row">생각해 볼 질문</th>${jobs.map(o=>`<td>${h(o.scenario.reflection)}</td>`).join('')}</tr><tr><th scope="row">국내 업무환경<br>만족·부담 요인</th>${jobs.map(()=>'<td>자료 수집 및 현직자 검토 필요</td>').join('')}</tr></tbody></table></div><div class="actionbar"><p>무엇이 나에게 더 흥미롭고, 무엇을 더 확인하고 싶나요?</p>${button('#notebook','비교한 내용 기록하기 →','light')}</div>`}${sourceNotice}`;
}
function storageControls() {
  return `<section class="panel no-print"><label class="check-label"><input type="checkbox" id="persist" ${persist?'checked':''} ${storageAvailable?'':'disabled'}> 이 기기에 기록 저장하기</label><p class="small">선택하지 않으면 새로고침·탭 종료 시 작성 내용이 사라집니다. 공용 PC에서는 저장하지 마세요. 서버 전송과 상담사 계정 연결은 없는 시제품입니다.</p><button class="button danger" id="clear">이 기기의 탐색 기록 삭제</button></section>`;
}
function field(key,label,help,value) {return `<label class="field">${label}<small>${help}</small><textarea maxlength="10000" data-field="${key}">${h(value)}</textarea></label>`;}
function renderNotebook(focusId) {
  const jobs=selectedJobs();const active=jobs.find(o=>o.id===focusId)||jobs[0];
  root.innerHTML=`<span class="eyebrow">MY EXPLORATION NOTES</span><h1 class="page-title">경험한 일을, 나의 말로.</h1><p class="lead">관심도와 부담감은 정답이 없습니다. 이 기록은 선택의 근거를 정리하기 위한 것이며 검사 점수를 만들지 않습니다.</p>${jobs.length<2?'<div class="notice">보고서를 만들려면 두 개 이상의 직업을 선택해야 합니다. <a href="#compare">비교 직업 선택하기</a></div>':''}${jobs.length?`<div class="progress">${jobs.map(o=>`<a class="button ${active.id===o.id?'':'secondary'}" href="#notebook/${o.id}">${h(o.name)}</a>`).join('')}</div><div class="layout"><div><section class="panel"><h2>${h(active.name)} 탐색 기록</h2><p><strong>${h(active.scenario.title)}</strong></p><p>${h(active.scenario.context)}</p><ol>${active.scenario.steps.map(s=>`<li>${h(s)}</li>`).join('')}</ol>${field('notes.'+active.id+'.work','활동 결과 *','사실·가설·추가 질문을 구분해 자유롭게 기록하세요.',state.notes[active.id]?.work)}${field('notes.'+active.id+'.interest','흥미로웠던 부분','어떤 과정이 흥미로웠으며, 그 이유는 무엇인가요?',state.notes[active.id]?.interest)}${field('notes.'+active.id+'.burden','부담스럽거나 더 알아볼 부분','한 번의 활동 경험을 직업 전체의 특징으로 단정하지 마세요.',state.notes[active.id]?.burden)}</section><section class="panel"><h2>직업을 비교한 나의 생각</h2>${field('comparison','새롭게 알게 된 차이 *','두 직업의 업무와 활동 과정에서 어떤 차이가 보였나요?',state.comparison)}${field('questions','상담에서 확인할 질문 *','근무 조건, 산업별 차이 등 아직 확인하지 못한 점을 적어 주세요.',state.questions)}${field('action','다음에 할 행동 *','예: 현직자 인터뷰에서 실제 협업 과정과 반복 업무를 질문한다.',state.action)}<label class="field">실행 예정일 <small>선택 입력</small><input type="date" data-field="due" value="${h(state.due)}"></label><div class="buttons"><button class="button" id="create-report">상담 보고서 만들기 →</button><button class="button secondary" id="export-notes">현재 기록 내려받기</button></div><p class="small">* 표시 항목은 보고서 생성에 필요합니다. 기존 보고서는 새 보고서를 만들기 전까지 유지됩니다.</p></section></div><aside><section class="panel"><h2>다음 탐색의 출발점</h2><ul>${active.scenario.next_steps.map(s=>`<li>${h(s)}</li>`).join('')}</ul><p class="small">위 항목은 활동 후 이어갈 수 있는 준비 예시입니다.</p><a href="#job/${active.id}">업무 근거 다시 보기 ↗</a></section>${storageControls()}</aside></div>`:'<div class="empty">먼저 탐색할 직업을 선택하세요. <a href="#explore">직업 탐색</a></div>'}`;
}
function renderReport() {
  const r=state.report;
  if(!r){root.innerHTML=`<span class="eyebrow">COUNSELING REPORT</span><h1 class="page-title">나의 진로 탐색 보고서</h1><div class="empty"><p>아직 만든 보고서가 없습니다. 두 직업의 활동과 비교 기록을 작성하면 보고서를 만들 수 있습니다.</p>${button('#notebook','탐색 기록 작성하기')}</div>`;return;}
  root.innerHTML=`<div class="section-head"><div><span class="eyebrow">MY CAREER EXPLORATION</span><h1 class="page-title">나의 진로 탐색 보고서</h1></div><div class="buttons no-print"><button class="button" id="print">인쇄 / PDF 저장</button><button class="button secondary" id="download-report">보고서 JSON</button></div></div><div class="report-meta"><span>작성 ${h(r.created_at.replace('T',' ').slice(0,16))} UTC</span><span>자료 버전 ${h(r.catalog_version)}</span><span>직업 정보 현직자 검토 전</span></div><p class="small">보고서 생성 시점의 기록과 근거를 보관한 초안입니다. ${r.occupations.length}개 직업을 비교했으며 적합도나 능력 점수는 산출하지 않았습니다.</p>${r.occupations.map(o=>`<section class="panel"><h2>${h(o.name)}</h2><h3>직업 탐색에 참고한 업무</h3>${(o.claims||[]).map(c=>`<p>${h(c.statement)} <span class="small">(${h(c.scope)} · 검토 전)</span></p>${(c.evidence||[]).map(e=>`<p class="small"><a href="${h(e.source.url)}" target="_blank" rel="noopener noreferrer">${h(e.source.title)}</a> · 확인 ${h(e.retrieved_at)}</p>`).join('')}`).join('')}<h3>활동 결과</h3><div class="report-answer">${h(o.notes.work)}</div><h3>흥미로웠던 부분</h3><div class="report-answer">${h(o.notes.interest||'기록하지 않음')}</div><h3>부담스럽거나 더 알아볼 부분</h3><div class="report-answer">${h(o.notes.burden||'기록하지 않음')}</div></section>`).join('')}<section class="panel"><h2>비교와 다음 행동</h2><h3>새롭게 알게 된 차이</h3><div class="report-answer">${h(r.comparison)}</div><h3>상담에서 확인할 질문</h3><div class="report-answer">${h(r.questions)}</div><h3>다음 행동 ${r.due?'· '+h(r.due):''}</h3><div class="report-answer">${h(r.action)}</div></section><section class="panel"><h2>상담 피드백</h2><p class="small">동일 기기에서 작성해 보는 시연용 메모입니다. 상담사 전송·인증 기능은 없습니다.</p><div class="report-answer" id="feedback-display">${h(r.feedback||'피드백 미작성')}</div><div class="no-print">${field('feedback','피드백 메모','보고서에 반영하려면 아래 버튼을 누르세요.',state.feedback)}<button class="button secondary" id="save-feedback">피드백을 보고서에 반영</button></div></section><div class="notice">자료의 국내 적용 범위와 직업별 근무 조건은 추가 확인이 필요합니다. 이 보고서는 진로 탐색 기록이며 심리검사 결과 또는 능력 평가서가 아닙니다.</div><div class="buttons no-print">${button('#notebook','탐색 기록 수정하기','secondary')}</div>`;
}
function render() {
  const [view,id]=(location.hash.slice(1)||'explore').split('/');
  document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===(view==='job'?'explore':view);el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  if(view==='explore')renderExplore();else if(view==='job')renderJob(id);else if(view==='compare')renderCompare();else if(view==='notebook')renderNotebook(id);else if(view==='report')renderReport();else {location.hash='explore';}
}
root.addEventListener('change',e=>{
  if(e.target.dataset.select){const id=e.target.dataset.select;if(e.target.checked)state.selected=[...new Set([...state.selected,id])];else state.selected=state.selected.filter(x=>x!==id);save();if(location.hash.startsWith('#compare'))renderCompare();else {const el=document.querySelector('#selection-count');if(el)el.textContent=`${state.selected.length}개 직업 선택 · 비교한 내용은 상담 보고서에 연결됩니다.`;}}
  if(e.target.id==='persist') {persist=e.target.checked;if(persist){save();e.target.checked=persist;}else {try{localStorage.removeItem(STORE_KEY);}catch{toast('저장된 기록을 삭제하지 못했습니다. 브라우저의 사이트 데이터 설정에서 삭제해 주세요.');return;}}toast(persist?'이 기기에 저장했습니다.':'기기 저장을 해제했습니다. 현재 탭의 기록은 유지됩니다.');}
});
root.addEventListener('input',e=>{
  const key=e.target.dataset.field;if(!key)return;
  if(key.startsWith('notes.')){const [,id,field]=key.split('.');state.notes[id]??={work:'',interest:'',burden:''};state.notes[id][field]=e.target.value;}else state[key]=e.target.value;save();
});
root.addEventListener('click',e=>{
  const id=e.target.closest('button')?.id;
  if(id==='create-report'){const errors=reportErrors(state);if(errors.length){toast(errors.join(' '));return;}state.report=makeReport(state,catalog);save();location.hash='report';}
  if(id==='export-notes')download('job-roadmap-notes.json',JSON.stringify({exported_at:new Date().toISOString(),catalog_version:catalog.release.version,...state},null,2));
  if(id==='download-report')download('job-roadmap-report.json',JSON.stringify(state.report,null,2));
  if(id==='print')window.print();
  if(id==='save-feedback'){state.report.feedback=state.feedback;state.report.feedback_updated_at=new Date().toISOString();save();document.querySelector('#feedback-display').textContent=state.feedback||'피드백 미작성';toast('이 보고서에 피드백을 반영했습니다.');}
  if(id==='clear'&&confirm('현재 탐색 기록과 이 기기에 저장한 기록을 삭제할까요? 내려받은 파일은 유지됩니다.')){try{localStorage.removeItem(STORE_KEY);}catch{toast('기기 저장 기록을 지우지 못했습니다. 브라우저 설정에서 사이트 데이터를 삭제해 주세요.');return;}state=emptyState();persist=false;render();toast('탐색 기록을 삭제했습니다.');}
});
window.addEventListener('hashchange',()=>{render();document.querySelector('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});
try {
  const response=await fetch('data/catalog.json');if(!response.ok)throw new Error('자료 요청 실패');catalog=await response.json();
  try{const saved=localStorage.getItem(STORE_KEY);if(saved){state=cleanState(JSON.parse(saved),catalog);persist=true;}}catch{storageAvailable=false;toast('저장된 기록을 읽지 못했습니다. 현재 탭에서 새로 시작합니다.');}
  render();
} catch {root.innerHTML='<div class="empty"><h1>자료를 불러오지 못했습니다.</h1><p>연결을 확인하고 새로고침해 주세요. 로컬 파일은 HTTP 서버에서 열어야 합니다.</p><button class="button" onclick="location.reload()">다시 시도</button></div>';}
